// Segment customers by activity
const customers = $input.all().map(item => item.json);
const now = new Date();
const daysSinceActivity = (dateStr) => {
  if (!dateStr) return 999;
  const date = new Date(dateStr);
  return Math.ceil((now - date) / (1000 * 60 * 60 * 24));
};

const segmented = customers.map(customer => {
  const daysSincePurchase = daysSinceActivity(customer.last_purchase);
  const daysSinceLogin = daysSinceActivity(customer.last_login);

  let segment = 'active';
  let campaign = 'none';

  if (daysSincePurchase > 90) {
    segment = 'churned';
    campaign = 'win_back';
  } else if (daysSincePurchase > 30) {
    segment = 'at_risk';
    campaign = 're_engage';
  } else {
    segment = 'active';
    campaign = 'nurture';
  }

  return {
    ...customer,
    segment,
    campaign,
    days_since_purchase: daysSincePurchase,
    days_since_login: daysSinceLogin,
    eligible_for_campaign: campaign !== 'none' && campaign !== 'nurture'
  };
});

const churned = segmented.filter(c => c.campaign === 'win_back');
const atRisk = segmented.filter(c => c.campaign === 're_engage');

console.log(`Segmented: ${atRisk.length} at-risk, ${churned.length} churned`);

return [
  ...atRisk.map(c => ({ json: c })),
  ...churned.map(c => ({ json: c }))
];
